                if (froze && g_ikFzSlot[j] != 0xFFFFu) std::memcpy(g_ikM0[j], g_pfzChain[g_ikFzSlot[j]], 64);
                else std::memcpy(g_ikM0[j], g_pfzAnim[j], 64);
