            nofoot::f167::Sample sample167;
            if (f167SpeedFresh) sample167.speed = g_pinMotion.speed;
            sample167.release = f167Release;
            sample167.detachW = bodyDetachForCall;
            sample167.leftW = pl.ok[0] && so[0].wrote ? so[0].wArm : 0.0;
